"""Coverage products are generated by the report phase and keep every status."""
import json

import pytest

from common.plan import matrix_metadata


def _scaling(ep_size):
    """A weak-scaling policy, so the two EP sizes normalise to the same workload.

    Weak scaling keeps the per-rank work constant and grows the expert count with the
    group, which is exactly the shape a cross-EP comparison must accept.
    """
    return {"mode": "weak", "tokens_per_rank": 8, "experts_per_rank": 8}


@pytest.fixture
def two_ep_run(run_report, task_for, record_for, manifest_for, config_for):
    tasks = []
    for ep_size in (8, 64):
        config = config_for(device="npu", ep_size=ep_size,
                            model={"num_experts": 8 * ep_size})
        config["scaling"] = _scaling(ep_size)
        tasks.append(task_for("COMM-001", backend_id="alltoall_hccl", ep_size=ep_size,
                              parameters={"variant": "default"}, index=ep_size,
                              config=config))
    tasks.append(task_for("COMM-002", backend_id="allgather_hccl", ep_size=8, index=99))
    manifest = manifest_for(tasks, run_id="coverage")
    rows = [record_for(manifest, tasks[0], "passed", p50=2.0),
            record_for(manifest, tasks[1], "passed", p50=1.0),
            record_for(manifest, tasks[2], "unsupported")]
    return run_report(tasks, rows, run_id="coverage", environment=manifest["environment"])


def test_report_phase_writes_every_coverage_product(two_ep_run):
    for name in ("coverage_matrix.md", "coverage_matrix.json", "coverage_matrix.csv",
                 "operator_coverage.md", "variant_coverage.md", "variant_coverage.csv",
                 "case_operator_coverage.csv", "ep_size_comparison.md", "l0_scaleout.md"):
        assert (two_ep_run.destination / name).is_file(), name


def test_ep_size_comparison_groups_two_ep_sizes(two_ep_run):
    text = (two_ep_run.destination / "ep_size_comparison.md").read_text(encoding="utf-8")
    assert "EP8" in text and "EP64" in text
    assert "COMM-001" in text
    data = json.loads((two_ep_run.destination / "coverage_matrix.json").read_text(
        encoding="utf-8"))
    comparable = [group for group in data["ep_size_comparison"]["groups"] if group["comparable"]]
    assert comparable
    assert {point["ep_size"] for point in comparable[0]["points"]} == {8, 64}


def test_single_ep_size_produces_no_scaling_group(run_report, task_for, record_for,
                                                  manifest_for, config_for):
    config = config_for(device="npu", ep_size=8)
    config["scaling"] = _scaling(8)
    tasks = [task_for("COMM-001", backend_id="alltoall_hccl", ep_size=8, index=0,
                      config=config)]
    manifest = manifest_for(tasks, run_id="one-ep")
    rows = [record_for(manifest, tasks[0], "passed", p50=1.0)]
    run = run_report(tasks, rows, run_id="one-ep", environment=manifest["environment"])
    data = json.loads((run.destination / "coverage_matrix.json").read_text(encoding="utf-8"))
    assert not [group for group in data["ep_size_comparison"]["groups"] if group["comparable"]]
    assert "Why EP Scalability Cannot Be Analysed" in run.text


def test_missing_task_is_counted_and_listed(two_ep_run):
    text = two_ep_run.text
    coverage_section = text[text.index("## 2. Test Coverage Summary"):text.index(
        "## 3. L0 Hardware Baseline")]
    assert "| Missing | 0 |" in coverage_section or "Missing" in coverage_section
    data = json.loads((two_ep_run.destination / "coverage_matrix.json").read_text(
        encoding="utf-8"))
    totals = data["case_operator_variant"]["totals"]
    assert totals["planned"] >= totals["results"]


def test_report_options_can_disable_the_comparison(run_report, task_for, record_for,
                                                   manifest_for):
    tasks = [task_for("COMM-001", backend_id="alltoall_hccl", index=0)]
    manifest = manifest_for(tasks, run_id="no-comparison")
    matrix = matrix_metadata(tasks)
    matrix["report"] = {**matrix.get("report", {}), "compare_ep_sizes": False}
    rows = [record_for(manifest, tasks[0], "passed", p50=1.0)]
    run = run_report(tasks, rows, run_id="no-comparison",
                     environment=manifest["environment"], matrix=matrix)
    assert not (run.destination / "ep_size_comparison.md").exists()
    assert "ep_size_comparison.md" not in run.text


def test_unsupported_is_never_counted_as_passed(two_ep_run):
    text = (two_ep_run.destination / "operator_coverage.md").read_text(encoding="utf-8")
    rows = [line for line in text.splitlines()
            if line.startswith("| EP") and "---" not in line and "| operator |" not in line]
    assert rows
    for row in rows:
        cells = [cell.strip() for cell in row.strip("|").split("|")]
        cases, passed = int(cells[2]), int(cells[3])
        assert passed <= cases


def test_alias_cases_are_marked_in_the_case_matrix(two_ep_run):
    text = (two_ep_run.destination / "coverage_matrix.md").read_text(encoding="utf-8")
    assert "alias->LINK-012" in text
    assert "out_of_scope" in text


def test_case_operator_csv_keeps_the_reason(run_report, task_for, record_for, manifest_for):
    tasks = [task_for("COMM-001", backend_id="alltoall_hccl", index=0)]
    manifest = manifest_for(tasks, run_id="reason")
    rows = [record_for(manifest, tasks[0], "unsupported",
                       extra={"error_reason": "operation requires dispatch"})]
    run = run_report(tasks, rows, run_id="reason", environment=manifest["environment"])
    csv = (run.destination / "case_operator_coverage.csv").read_text(encoding="utf-8")
    assert "operation requires dispatch" in csv


def test_coverage_matrix_json_carries_every_dimension(two_ep_run):
    data = json.loads((two_ep_run.destination / "coverage_matrix.json").read_text(
        encoding="utf-8"))
    for key in ("ep_sizes", "cases", "operators", "case_operator", "case_operator_variant",
                "ep_size_comparison", "l0_scaleout", "topology", "execution"):
        assert key in data, key
    assert set(data["ep_sizes"]) == {8, 64}
